import pytest


def pick(xs: list[int], seed: int) -> int:
    """Deterministically pick an element of xs from an integer seed.

    The same xs and seed always give the same element. No randomness is
    used. Any integer seed is valid, including negative and very large
    values. The input list is not modified.

    Raises ValueError if xs is empty.
    """
    if not xs:
        raise ValueError("xs must be non-empty")
    return xs[seed % len(xs)]


def test_result_is_member() -> None:
    xs = [10, 20, 30, 40]
    for seed in range(-20, 20):
        assert pick(xs, seed) in xs


def test_same_seed_same_element() -> None:
    xs = [5, 8, 13, 21, 34]
    for seed in (0, 1, 7, -3, 10**18, -(10**18)):
        assert pick(xs, seed) == pick(xs, seed)
        assert pick(list(xs), seed) == pick(xs, seed)


def test_single_element() -> None:
    for seed in (0, 1, -1, 12345, -98765, 10**30):
        assert pick([42], seed) == 42


def test_all_elements_reachable() -> None:
    xs = [3, 1, 4, 15, 9, 2]
    picked = {pick(xs, seed) for seed in range(len(xs))}
    assert picked == set(xs)


def test_all_elements_reachable_with_many_seeds() -> None:
    xs = [7, 8, 9]
    picked = {pick(xs, seed) for seed in range(-50, 50)}
    assert picked == set(xs)


def test_duplicates_allowed() -> None:
    xs = [2, 2, 2]
    for seed in range(-5, 5):
        assert pick(xs, seed) == 2


def test_negative_and_large_seeds() -> None:
    xs = [1, 2, 3, 4, 5]
    assert pick(xs, -1) in xs
    assert pick(xs, -(10**20)) in xs
    assert pick(xs, 10**20) in xs


def test_input_not_mutated() -> None:
    xs = [9, 8, 7, 6]
    copy = list(xs)
    pick(xs, 3)
    pick(xs, -11)
    assert xs == copy


def test_empty_raises() -> None:
    with pytest.raises(ValueError):
        pick([], 0)
